// seed: tests/seed.admin.spec.ts
// #9301886c — окно «החזרה לספק»: товар и на полке, и «ללא מקום» = две строки (товар + место), выбираются раздельно;
// поиск фильтрует; счётчик/кнопка по отмеченным; возврат снимает из выбранного источника; несколько возвратов отправляются все;
// частичный сбой (создаётся вторым контекстом, как в ручном прогоне) — у каждой упавшей строки своя причина.
// Данные: A «QA-AUTO-9301-<ts>-a» привязан к СВОБОДНОЙ «ריק» полке шкафа G («קומה 1», выбирается при прогоне),
//         B «QA-AUTO-9301-<ts>-b» только «ללא מקום».
// ⚠️ Возвраты поставщику и записи «יומן תנועות» НЕОБРАТИМЫ (журнал не удаляется): всего 8 возвратов по 1–2 шт.
// Не запускать одновременно с другими тестами, которые занимают полки G (inventory/delete-*, catalog/location-cell-multi-places).
// afterAll: «הסרה מהמקום» у A, удаление A и B (уходят в архив — есть движения), полка снова «ריק».
import { test, expect, Page, Browser, Response, Locator } from '@playwright/test';
import {
  ADMIN, Place, Used, track, cleanup, createProduct, pickEmptyPlaces, bindPlace, receive,
  expectStock, openPlace, qtyInPlacePanel,
} from '../inventory/_places';

test.use({ storageState: ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const KEY = `QA-AUTO-9301-${TS}`;
const A = `${KEY}-a`;
const B = `${KEY}-b`;
const REF = (s: string) => `${KEY}-${s}`;
const POOL = 'ללא שיוך למקום';

const created = new Set<string>();
const used: Used = new Map();
let place: Place | null = null;
const shelfLabel = () => `מדף ${place!.code}`;

// ---------- окно «החזרה לספק» ----------
async function openSupplierReturn(page: Page, search: string) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: 'החזרות' }).click();
  await page.getByRole('menuitem', { name: /^החזרה לספק/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'החזרה לספק' })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'חיפוש פריט' }).fill(search);
  return dlg;
}

/** Чекбокс строки «<שם> · <מק"ט> זמין N · <מקום>» (avail — число или любое). */
const box = (dlg: Locator, p: string, place: string, avail: number | null = null) =>
  dlg.getByRole('checkbox', { name: new RegExp(`^${p} · \\S+ זמין ${avail ?? '\\d+'} · ${place}$`) });

/** Поле кол-ва — внутри строки (у двух строк одного товара одинаковый aria-label «כמות ל<שם>»). */
const qtyOf = (dlg: Locator, p: string, place: string) =>
  box(dlg, p, place).locator('xpath=ancestor::label[1]/parent::*').getByRole('spinbutton', { name: `כמות ל${p}` });

async function mark(dlg: Locator, p: string, place: string, qty: number) {
  await box(dlg, p, place).check();
  await qtyOf(dlg, p, place).fill(String(qty));
}

/** Сборщик ответов rpc/return_to_supplier на странице. */
function watchReturns(page: Page) {
  const list: Response[] = [];
  page.on('response', (r) => {
    if (r.url().includes('/rpc/return_to_supplier') && r.request().method() === 'POST') list.push(r);
  });
  return list;
}

async function waitReturns(list: Response[], n: number) {
  await expect.poll(() => list.length, { timeout: 30_000, message: `ожидалось ${n} запросов return_to_supplier` }).toBe(n);
  return Promise.all(list.map(async (r) => ({
    status: r.status(),
    loc: r.request().postDataJSON()?.p_location_id ?? null,
    body: await r.text().catch(() => ''),
  })));
}

/** Второе окно (контекст) админа — им «опережаем» первое, чтобы вызвать сбой части строк. */
async function secondAdmin(browser: Browser) {
  const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  return { ctx, page: await ctx.newPage() };
}

// ---------- журнал ----------
/** Все карточки «החזרה לספק» с данной אסמכתא → строки текста каждой карточки. */
async function journalReturns(page: Page, search: string, ref: string, expected: number) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 30_000 });
  const expand = page.getByRole('button', { name: 'פתיחת יומן התנועות' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await page.getByRole('textbox', { name: 'חיפוש ביומן התנועות' }).fill(search);
  const cards = page.getByText(ref, { exact: true }).locator('xpath=ancestor::div[.//*[normalize-space()="החזרה לספק"]][1]');
  await expect(cards).toHaveCount(expected, { timeout: 20_000 });
  return (await cards.allInnerTexts()).map((t) => t.split('\n').map((s) => s.trim()).filter(Boolean));
}

/** Есть карточка: источник from, товар p, кол-во qty, «test admin». */
function expectEntry(cards: string[][], from: string, p: string, qty: number) {
  const hit = cards.filter((l) => l.includes(from) && l.some((x) => x.startsWith(`${p} · `)) && l.includes(String(qty)));
  expect(hit, `журнал: «החזרה לספק» ${from} · ${p} · ${qty}\n${JSON.stringify(cards)}`).toHaveLength(1);
  expect(hit[0]).toContain('החזרה לספק');
  expect(hit[0]).toContain('test admin');
}

/** Текст сбоя строки: «‹товар› · <место>: <причина>» (имя может быть в bidi-изоляторах). */
const failLine = (p: string, place: string, reason: string) =>
  new RegExp(`${p}.? · ${place}: ${reason.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`);

test.describe('warehouse-map — החזרה לספק: שורה = מוצר + מקום (#9301886c)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await cleanup(browser, created, used);
  });

  test('מוצר במדף וגם «ללא מקום» — שתי שורות נפרדות: סימון וכמות לכל שורה, חיפוש מסנן, המונה והכפתור לפי הסימון #9301886c @desktop @data', async ({ page }) => {
    test.setTimeout(360_000);
    [place] = await pickEmptyPlaces(page, 1, ['G']);
    await createProduct(page, A, `QA9301A${TS}`, created);
    await createProduct(page, B, `QA9301B${TS}`, created);
    track(used, A, place);
    await bindPlace(page, A, place);
    await receive(page, A, 2, place.code);
    await receive(page, A, 2, null);
    await receive(page, B, 1, null);

    const calls = watchReturns(page);
    const dlg = await openSupplierReturn(page, KEY);
    const submit = dlg.getByRole('button', { name: /^רישום / });
    // 3 строки: A·полка, A·«ללא מקום», B·«ללא מקום»
    await expect(dlg.getByRole('checkbox')).toHaveCount(3);
    await expect(box(dlg, A, shelfLabel(), 2)).toBeVisible();
    await expect(box(dlg, A, POOL, 2)).toBeVisible();
    await expect(box(dlg, B, POOL, 1)).toBeVisible();
    await expect(dlg).toContainText('3 פריטים');

    // Т1: отмечаем только «ללא מקום» у A — полка A не отмечается
    await box(dlg, A, POOL).check();
    await expect(box(dlg, A, POOL)).toBeChecked();
    await expect(box(dlg, A, shelfLabel())).not.toBeChecked();
    await expect(qtyOf(dlg, A, shelfLabel())).toHaveCount(0);
    await expect(qtyOf(dlg, A, POOL)).toHaveValue('2');
    await expect(dlg).toContainText('1 מתוך 3 נבחרו');
    await expect(submit).toHaveText('רישום ההחזרה');

    // своя кол-во у каждой строки; снятие полки не снимает «ללא מקום»
    await box(dlg, A, shelfLabel()).check();
    await qtyOf(dlg, A, shelfLabel()).fill('1');
    await expect(qtyOf(dlg, A, POOL)).toHaveValue('2');
    await expect(dlg).toContainText('2 מתוך 3 נבחרו');
    await expect(submit).toHaveText('רישום 2 החזרות');
    await box(dlg, A, shelfLabel()).uncheck();
    await expect(box(dlg, A, POOL)).toBeChecked();
    await expect(qtyOf(dlg, A, POOL)).toHaveValue('2');
    await expect(dlg).toContainText('1 מתוך 3 נבחרו');

    // Т2/Т3: поиск по B — только строка B; отмеченные вне поиска — «עוד N מסומנים מחוץ לחיפוש»
    const search = dlg.getByRole('textbox', { name: 'חיפוש פריט' });
    await search.fill(B);
    await expect(dlg.getByRole('checkbox')).toHaveCount(1);
    await expect(box(dlg, B, POOL)).toBeVisible();
    await expect(dlg).toContainText('פריט אחד · עוד 1 מסומנים מחוץ לחיפוש');
    await box(dlg, B, POOL).check();
    await expect(submit).toHaveText('רישום 2 החזרות');

    // «בחירת הכל» / «ניקוי הבחירה» — только по строкам на экране
    await search.fill(A);
    await expect(dlg.getByRole('checkbox')).toHaveCount(2);
    await dlg.getByRole('button', { name: 'בחירת הכל' }).click();
    await expect(box(dlg, A, shelfLabel())).toBeChecked();
    await expect(dlg).toContainText('2 מתוך 2 נבחרו · עוד 1 מסומנים מחוץ לחיפוש');
    await expect(submit).toHaveText('רישום 3 החזרות');
    await dlg.getByRole('button', { name: 'ניקוי הבחירה' }).click();
    await expect(box(dlg, A, shelfLabel())).not.toBeChecked();
    await expect(box(dlg, A, POOL)).not.toBeChecked();

    // после очистки поиска строк = счётчику, отмечена только B
    await search.fill(KEY);
    await expect(dlg.getByRole('checkbox')).toHaveCount(3);
    await expect(dlg).toContainText('1 מתוך 3 נבחרו');
    await expect(box(dlg, B, POOL)).toBeChecked();
    await expect(submit).toHaveText('רישום ההחזרה');

    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    expect(calls.length, 'запроса return_to_supplier быть не должно').toBe(0);
    await expectStock(page, A, 4);
    await expectStock(page, B, 1);
  });

  test('כמה החזרות נשלחות כולן; «ללא מקום» יורד רק מ«ללא מקום», מדף — רק מהמדף; יומן לכל אחת #9301886c @desktop @data', async ({ page }) => {
    test.setTimeout(300_000);
    test.skip(!place, 'нет данных из предыдущего теста');
    const calls = watchReturns(page);
    const dlg = await openSupplierReturn(page, KEY);
    await mark(dlg, A, POOL, 1);
    await mark(dlg, A, shelfLabel(), 1);
    await mark(dlg, B, POOL, 1);
    await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(REF('m'));
    await dlg.getByRole('button', { name: 'רישום 3 החזרות' }).click();
    const res = await waitReturns(calls, 3);
    expect(res.map((r) => r.status), JSON.stringify(res)).toEqual([200, 200, 200]);
    expect(res.filter((r) => r.loc === null), 'два запроса «ללא מקום» (p_location_id null)').toHaveLength(2);
    expect(res.filter((r) => r.loc !== null), 'один запрос с полки').toHaveLength(1);
    await expect(dlg).toHaveCount(0, { timeout: 15_000 });

    // остатки: A 4 → 2 (по 1 из каждого источника), B 1 → 0; в полке A 2 → 1
    await expectStock(page, A, 2);
    await expectStock(page, B, 0);
    await openPlace(page, place!);
    await expect.poll(() => qtyInPlacePanel(page, A), { timeout: 15_000 }).toBe(1);
    const again = await openSupplierReturn(page, KEY);
    await expect(box(again, A, shelfLabel(), 1)).toBeVisible();
    await expect(box(again, A, POOL, 1)).toBeVisible();
    await expect(box(again, B, POOL)).toHaveCount(0);
    await again.getByRole('button', { name: 'ביטול' }).click();

    // журнал: 3 записи с источником каждой строки
    const cards = await journalReturns(page, KEY, REF('m'), 3);
    expectEntry(cards, 'ללא מקום', A, 1);
    expectEntry(cards, place!.code, A, 1);
    expectEntry(cards, 'ללא מקום', B, 1);
  });

  test('כשל חלקי — חוסר מלאי: שאר ההחזרות נשלחות; ל«ללא מקום» ולמדף מוצגת הסיבה «יש N יחידות בלבד» #9301886c @desktop @data', async ({ page, browser }) => {
    test.setTimeout(360_000);
    test.skip(!place, 'нет данных из предыдущего теста');
    // A: полка 1→2, «ללא מקום» 1→2; B: 0→1
    await receive(page, A, 1, place!.code);
    await receive(page, A, 1, null);
    await receive(page, B, 1, null);

    const calls = watchReturns(page);
    const dlg = await openSupplierReturn(page, KEY);
    await mark(dlg, A, POOL, 2);
    await mark(dlg, A, shelfLabel(), 2);
    await mark(dlg, B, POOL, 1);
    await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(REF('a1'));

    // второе окно: возвращает по 1 из обоих источников A — в первом окне остаток устарел
    const two = await secondAdmin(browser);
    try {
      const calls2 = watchReturns(two.page);
      const d2 = await openSupplierReturn(two.page, A);
      await mark(d2, A, POOL, 1);
      await mark(d2, A, shelfLabel(), 1);
      await d2.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(REF('a2'));
      await d2.getByRole('button', { name: 'רישום 2 החזרות' }).click();
      expect((await waitReturns(calls2, 2)).map((r) => r.status)).toEqual([200, 200]);
      await expect(d2).toHaveCount(0, { timeout: 15_000 });
    } finally {
      await two.ctx.close();
    }

    await dlg.getByRole('button', { name: 'רישום 3 החזרות' }).click();
    const res = await waitReturns(calls, 3);
    expect(res.filter((r) => r.status === 200), JSON.stringify(res)).toHaveLength(1);
    await expect(dlg).toBeVisible();
    await expect(dlg).toContainText('נרשמו 1 מתוך 3 החזרות.', { timeout: 15_000 });
    await expect(dlg).toContainText(failLine(A, POOL, 'ללא שיוך למקום יש 1 יחידות בלבד.'));
    await expect(dlg).toContainText(failLine(A, shelfLabel(), `ב${place!.code} יש 1 יחידות בלבד.`));
    await expect(dlg).not.toContainText('רישום ההחזרה נכשל');
    await dlg.getByRole('button', { name: 'ביטול' }).click();

    // B ушёл; у A сняты только 2 шт. вторым окном (4 → 2)
    await expectStock(page, B, 0);
    await expectStock(page, A, 2);
  });

  test('כשל חלקי — אין מלאי בכלל ב«ללא מקום»: «אין מלאי של הפריט להחזרה.», המדף נשלח #9301886c @desktop @data', async ({ page, browser }) => {
    test.setTimeout(300_000);
    test.skip(!place, 'нет данных из предыдущего теста');
    // A: полка 1, «ללא מקום» 1
    const calls = watchReturns(page);
    const dlg = await openSupplierReturn(page, KEY);
    await mark(dlg, A, POOL, 1);
    await mark(dlg, A, shelfLabel(), 1);
    await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(REF('b1'));

    const two = await secondAdmin(browser);
    try {
      const calls2 = watchReturns(two.page);
      const d2 = await openSupplierReturn(two.page, A);
      await mark(d2, A, POOL, 1);
      await d2.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(REF('b2'));
      await d2.getByRole('button', { name: 'רישום ההחזרה' }).click();
      expect((await waitReturns(calls2, 1)).map((r) => r.status)).toEqual([200]);
      await expect(d2).toHaveCount(0, { timeout: 15_000 });
    } finally {
      await two.ctx.close();
    }

    await dlg.getByRole('button', { name: 'רישום 2 החזרות' }).click();
    const res = await waitReturns(calls, 2);
    expect(res.filter((r) => r.status === 200), JSON.stringify(res)).toHaveLength(1);
    await expect(dlg).toBeVisible();
    await expect(dlg).toContainText('נרשמו 1 מתוך 2 החזרות.', { timeout: 15_000 });
    await expect(dlg).toContainText(failLine(A, POOL, 'אין מלאי של הפריט להחזרה.'));
    await expect(dlg).not.toContainText('רישום ההחזרה נכשל');
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expectStock(page, A, 0);
  });
});
